PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS cortes(id TEXT PRIMARY KEY, quincena TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT NOT NULL, source_hash TEXT NOT NULL, source_name TEXT NOT NULL, expected TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'BORRADOR', validation TEXT);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS personas(corte TEXT NOT NULL REFERENCES cortes(id), matricula TEXT NOT NULL, nombre_search TEXT NOT NULL, tc TEXT NOT NULL, status TEXT NOT NULL, json TEXT NOT NULL CHECK(json_valid(json)), PRIMARY KEY(corte,matricula));
CREATE INDEX IF NOT EXISTS personas_search ON personas(corte,nombre_search);
CREATE TABLE IF NOT EXISTS plazas(corte TEXT NOT NULL REFERENCES cortes(id), plaza TEXT NOT NULL, ocupante TEXT, titular TEXT, puesto TEXT, departamento TEXT, json TEXT NOT NULL CHECK(json_valid(json)), PRIMARY KEY(corte,plaza));
CREATE INDEX IF NOT EXISTS plazas_ocupante ON plazas(corte,ocupante);
CREATE TABLE IF NOT EXISTS antiguedad(corte TEXT NOT NULL REFERENCES cortes(id), matricula TEXT NOT NULL, json TEXT NOT NULL CHECK(json_valid(json)), PRIMARY KEY(corte,matricula));
CREATE TABLE IF NOT EXISTS catalogos(corte TEXT NOT NULL REFERENCES cortes(id), clave TEXT NOT NULL, json TEXT NOT NULL CHECK(json_valid(json)), PRIMARY KEY(corte,clave));
CREATE TABLE IF NOT EXISTS chunks(corte TEXT NOT NULL REFERENCES cortes(id), dataset TEXT NOT NULL, numero INTEGER NOT NULL, hash TEXT NOT NULL, PRIMARY KEY(corte,dataset,numero));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, usuario TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS auth_limits(key TEXT PRIMARY KEY, intentos INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, corte TEXT, accion TEXT NOT NULL, usuario TEXT NOT NULL, fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS curriculum_files(id TEXT PRIMARY KEY,owner TEXT NOT NULL,recipient TEXT NOT NULL,name TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS curriculum_chunks(file TEXT NOT NULL REFERENCES curriculum_files(id),numero INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(file,numero));
CREATE INDEX IF NOT EXISTS curriculum_owner ON curriculum_files(owner,recipient);
CREATE TABLE IF NOT EXISTS pase_folios(id INTEGER PRIMARY KEY AUTOINCREMENT,request_id TEXT UNIQUE NOT NULL,owner TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contrataciones(id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT NOT NULL UNIQUE,request_key TEXT NOT NULL UNIQUE,creator TEXT NOT NULL,corte TEXT NOT NULL REFERENCES cortes(id),quincena TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'BORRADOR',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),plan TEXT NOT NULL CHECK(json_valid(plan)));
CREATE INDEX IF NOT EXISTS contrataciones_owner ON contrataciones(creator,id);
CREATE INDEX IF NOT EXISTS contrataciones_estado ON contrataciones(estado,id);
CREATE TABLE IF NOT EXISTS contratacion_events(id TEXT PRIMARY KEY,solicitud TEXT NOT NULL REFERENCES contrataciones(uuid),actor TEXT NOT NULL,accion TEXT NOT NULL,fecha TEXT NOT NULL,detalle TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cobertura_jornadas(id TEXT PRIMARY KEY,quincena TEXT NOT NULL,unidad TEXT NOT NULL,nombre TEXT NOT NULL,categorias TEXT NOT NULL,horas REAL NOT NULL,tarifa_centavos INTEGER NOT NULL CHECK(tarifa_centavos>0),presupuesto_centavos INTEGER NOT NULL CHECK(presupuesto_centavos>=0),estado TEXT NOT NULL DEFAULT 'BORRADOR',version INTEGER NOT NULL DEFAULT 1,actualizado_por TEXT NOT NULL,actualizado_en TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cobertura_reservas(solicitud TEXT PRIMARY KEY REFERENCES contrataciones(uuid),jornada TEXT NOT NULL REFERENCES cobertura_jornadas(id),centavos INTEGER NOT NULL CHECK(centavos>0));
CREATE TABLE IF NOT EXISTS cobertura_config_audit(id TEXT PRIMARY KEY,tipo TEXT NOT NULL,registro TEXT NOT NULL,actor TEXT NOT NULL,fecha TEXT NOT NULL,datos TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cobertura_tabuladores(id TEXT PRIMARY KEY,quincena TEXT NOT NULL,nombre TEXT NOT NULL,datos TEXT NOT NULL,hash TEXT NOT NULL,creado_por TEXT NOT NULL,creado_en TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS cobertura_tab_qna ON cobertura_tabuladores(quincena,creado_en);
CREATE TABLE IF NOT EXISTS cobertura_firmantes(owner TEXT NOT NULL,trabajador TEXT NOT NULL,jefe TEXT NOT NULL,dependencia TEXT NOT NULL,PRIMARY KEY(owner,trabajador));
CREATE TRIGGER IF NOT EXISTS cobertura_reglas_fijas BEFORE UPDATE ON cobertura_jornadas WHEN EXISTS(SELECT 1 FROM cobertura_reservas WHERE jornada=OLD.id) BEGIN SELECT RAISE(ABORT,'La jornada tiene presupuesto comprometido'); END;
CREATE TABLE IF NOT EXISTS cobertura_presupuestos(quincena TEXT NOT NULL,unidad TEXT NOT NULL,centavos INTEGER NOT NULL CHECK(centavos>=0),version INTEGER NOT NULL DEFAULT 1,actor TEXT NOT NULL,fecha TEXT NOT NULL,PRIMARY KEY(quincena,unidad));
DROP TRIGGER IF EXISTS cobertura_saldo;
CREATE TRIGGER IF NOT EXISTS cobertura_saldo BEFORE INSERT ON cobertura_reservas BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM cobertura_jornadas WHERE id=NEW.jornada AND estado='AUTORIZADA') OR NEW.centavos+COALESCE((SELECT SUM(r.centavos) FROM cobertura_reservas r JOIN cobertura_jornadas j ON j.id=r.jornada WHERE j.quincena=(SELECT quincena FROM cobertura_jornadas WHERE id=NEW.jornada) AND j.unidad=(SELECT unidad FROM cobertura_jornadas WHERE id=NEW.jornada)),0)>COALESCE((SELECT p.centavos FROM cobertura_presupuestos p JOIN cobertura_jornadas j ON p.quincena=j.quincena AND p.unidad=j.unidad WHERE j.id=NEW.jornada),0) THEN RAISE(ABORT,'Presupuesto insuficiente o jornada no autorizada') END; END;
CREATE TRIGGER IF NOT EXISTS cobertura_presupuesto_minimo BEFORE UPDATE ON cobertura_presupuestos WHEN NEW.centavos<COALESCE((SELECT SUM(r.centavos) FROM cobertura_reservas r JOIN cobertura_jornadas j ON r.jornada=j.id WHERE j.quincena=OLD.quincena AND j.unidad=OLD.unidad),0) BEGIN SELECT RAISE(ABORT,'Presupuesto inferior al comprometido'); END;
CREATE TABLE IF NOT EXISTS pases_registros(folio TEXT PRIMARY KEY,alias TEXT UNIQUE NOT NULL,matricula TEXT NOT NULL,creator TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),estado TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS pases_registros_matricula ON pases_registros(matricula,updated_at);
CREATE TABLE IF NOT EXISTS normativa_documentos(id TEXT PRIMARY KEY,clave TEXT NOT NULL,titulo TEXT NOT NULL,nombre TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT UNIQUE NOT NULL,paginas INTEGER NOT NULL,ambito TEXT NOT NULL,version TEXT NOT NULL,privado INTEGER NOT NULL DEFAULT 0,ocr INTEGER NOT NULL DEFAULT 0,publicado INTEGER NOT NULL DEFAULT 0,creado_en TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS normativa_archivos(documento TEXT NOT NULL REFERENCES normativa_documentos(id),numero INTEGER NOT NULL,data TEXT NOT NULL,bytes INTEGER NOT NULL,PRIMARY KEY(documento,numero));
CREATE VIRTUAL TABLE IF NOT EXISTS normativa_indice USING fts5(documento UNINDEXED,pagina UNINDEXED,texto,tokenize='unicode61 remove_diacritics 2');
CREATE TABLE IF NOT EXISTS vacaciones_periodos(id TEXT PRIMARY KEY,matricula TEXT NOT NULL,corte TEXT NOT NULL REFERENCES cortes(id),anio INTEGER NOT NULL,numero TEXT NOT NULL,regimen TEXT NOT NULL,modalidad TEXT NOT NULL,total INTEGER NOT NULL CHECK(total>=0),payload TEXT NOT NULL,snapshot TEXT NOT NULL,actor TEXT NOT NULL,fecha TEXT NOT NULL,UNIQUE(matricula,anio,regimen,modalidad,numero));
CREATE TABLE IF NOT EXISTS vacaciones_registros(id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT UNIQUE NOT NULL,request_key TEXT UNIQUE NOT NULL,periodo TEXT NOT NULL REFERENCES vacaciones_periodos(id),matricula TEXT NOT NULL,creator TEXT NOT NULL,tipo TEXT NOT NULL,original TEXT,estado TEXT NOT NULL DEFAULT 'BORRADOR',version INTEGER NOT NULL DEFAULT 1,payload TEXT NOT NULL,plan TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,pago TEXT NOT NULL DEFAULT 'SIN_SOLICITUD',pago_referencia TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS vacaciones_reg_mat ON vacaciones_registros(matricula,updated_at);
CREATE TABLE IF NOT EXISTS vacaciones_eventos(id TEXT PRIMARY KEY,registro TEXT NOT NULL,accion TEXT NOT NULL,actor TEXT NOT NULL,fecha TEXT NOT NULL,detalle TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vacaciones_reservas(registro TEXT PRIMARY KEY REFERENCES vacaciones_registros(uuid),periodo TEXT NOT NULL REFERENCES vacaciones_periodos(id),dias INTEGER NOT NULL CHECK(dias>=0));
CREATE TRIGGER IF NOT EXISTS vacaciones_saldo BEFORE INSERT ON vacaciones_reservas WHEN NEW.dias+COALESCE((SELECT SUM(dias) FROM vacaciones_reservas WHERE periodo=NEW.periodo),0)>(SELECT total FROM vacaciones_periodos WHERE id=NEW.periodo) BEGIN SELECT RAISE(ABORT,'Saldo vacacional insuficiente'); END;
CREATE TABLE IF NOT EXISTS vacaciones_jornadas(registro TEXT NOT NULL,matricula TEXT NOT NULL,fecha TEXT NOT NULL,PRIMARY KEY(matricula,fecha));
CREATE TABLE IF NOT EXISTS vacaciones_assert(id TEXT PRIMARY KEY,value INTEGER NOT NULL CHECK(value=1));
CREATE TABLE IF NOT EXISTS vacaciones_coberturas(id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT UNIQUE NOT NULL,request_key TEXT UNIQUE NOT NULL,registro TEXT NOT NULL,matricula TEXT NOT NULL,plaza TEXT NOT NULL,corte TEXT NOT NULL,inicio TEXT NOT NULL,fin TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'ASIGNADA',payload TEXT NOT NULL,actor TEXT NOT NULL,fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vacaciones_cobertura_dias(matricula TEXT NOT NULL,fecha TEXT NOT NULL,cobertura TEXT NOT NULL,PRIMARY KEY(matricula,fecha));
CREATE TABLE IF NOT EXISTS vacaciones_cobertura_cierre(matricula TEXT NOT NULL,anio INTEGER NOT NULL,actor TEXT NOT NULL,fecha TEXT NOT NULL,PRIMARY KEY(matricula,anio));

CREATE UNIQUE INDEX IF NOT EXISTS vacaciones_cobertura_activa ON vacaciones_coberturas(registro) WHERE estado='ASIGNADA';
CREATE TRIGGER IF NOT EXISTS vacaciones_no_cubrir_ausente BEFORE INSERT ON vacaciones_cobertura_dias WHEN EXISTS(SELECT 1 FROM vacaciones_jornadas WHERE matricula=NEW.matricula AND fecha=NEW.fecha) BEGIN SELECT RAISE(ABORT,'El cubre-vacaciones tiene vacaciones propias'); END;
CREATE TRIGGER IF NOT EXISTS vacaciones_no_ausencia_cubriendo BEFORE INSERT ON vacaciones_jornadas WHEN EXISTS(SELECT 1 FROM vacaciones_cobertura_dias WHERE matricula=NEW.matricula AND fecha=NEW.fecha) BEGIN SELECT RAISE(ABORT,'La fecha tiene una cobertura asignada; reordenar'); END;
CREATE TABLE IF NOT EXISTS vacaciones_reposiciones(registro TEXT NOT NULL,original TEXT NOT NULL,fecha TEXT NOT NULL,PRIMARY KEY(original,fecha));
CREATE TABLE IF NOT EXISTS vacaciones_adjuntos(id TEXT PRIMARY KEY,registro TEXT NOT NULL,owner TEXT NOT NULL,nombre TEXT NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vacaciones_adjunto_chunks(archivo TEXT NOT NULL REFERENCES vacaciones_adjuntos(id),numero INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(archivo,numero));

CREATE TRIGGER IF NOT EXISTS vacaciones_cobertura_validada BEFORE INSERT ON vacaciones_coberturas WHEN EXISTS(SELECT 1 FROM vacaciones_cobertura_cierre WHERE matricula=NEW.matricula AND anio=2027) OR NOT EXISTS(SELECT 1 FROM vacaciones_registros WHERE uuid=NEW.registro AND estado IN ('AUTORIZADA','CAPTURADA_SIAP')) BEGIN SELECT RAISE(ABORT,'Programación cerrada o vacaciones sin autorización vigente'); END;
CREATE TRIGGER IF NOT EXISTS vacaciones_reordenar_antes BEFORE UPDATE OF plan,estado ON vacaciones_registros WHEN (NEW.plan<>OLD.plan OR NEW.estado IN ('CANCELADA','SUSTITUIDA')) AND EXISTS(SELECT 1 FROM vacaciones_coberturas WHERE registro=OLD.uuid AND estado='ASIGNADA') BEGIN SELECT RAISE(ABORT,'Reordena la cobertura antes de modificar las vacaciones'); END;

CREATE TRIGGER IF NOT EXISTS vacaciones_previo_vigente BEFORE INSERT ON vacaciones_reservas WHEN EXISTS(SELECT 1 FROM vacaciones_registros r WHERE r.uuid=NEW.registro AND json_extract(r.payload,'$.antecedente_uuid') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vacaciones_registros p WHERE p.uuid=json_extract(r.payload,'$.antecedente_uuid') AND p.matricula=r.matricula AND p.estado IN ('AUTORIZADA','CAPTURADA_SIAP','DISFRUTADA') AND json_extract(p.plan,'$.fin')<json_extract(r.plan,'$.inicio'))) BEGIN SELECT RAISE(ABORT,'El periodo previo cambió o dejó de estar autorizado'); END;
CREATE TRIGGER IF NOT EXISTS vacaciones_proteger_secuencia BEFORE UPDATE OF estado,plan ON vacaciones_registros WHEN EXISTS(SELECT 1 FROM vacaciones_registros s WHERE json_extract(s.payload,'$.antecedente_uuid')=OLD.uuid AND s.estado IN ('AUTORIZADA','CAPTURADA_SIAP','DISFRUTADA') AND (NEW.estado IN ('CANCELADA','SUSTITUIDA') OR json_extract(NEW.plan,'$.fin')>=json_extract(s.plan,'$.inicio'))) BEGIN SELECT RAISE(ABORT,'Existe un segundo periodo encadenado autorizado'); END;
CREATE TABLE IF NOT EXISTS vacaciones_calendarios(registro TEXT NOT NULL REFERENCES vacaciones_registros(uuid),tipo TEXT NOT NULL CHECK(tipo IN ('MADRE','REAL')),origen TEXT NOT NULL,actual TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(registro,tipo));
CREATE TABLE IF NOT EXISTS contactos(matricula TEXT PRIMARY KEY,institucional TEXT NOT NULL DEFAULT '',personal TEXT NOT NULL DEFAULT '',institucional_verificado TEXT,personal_verificado TEXT,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notificaciones(id TEXT PRIMARY KEY,event_key TEXT UNIQUE NOT NULL,matricula TEXT NOT NULL,titulo TEXT NOT NULL,mensaje TEXT NOT NULL,url TEXT NOT NULL,fecha TEXT NOT NULL,leida TEXT,expandida INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS notificaciones_propias ON notificaciones(matricula,fecha);
CREATE TABLE IF NOT EXISTS push_suscripciones(id TEXT PRIMARY KEY,matricula TEXT NOT NULL,endpoint TEXT UNIQUE NOT NULL,p256dh TEXT NOT NULL,auth TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS push_owner ON push_suscripciones(matricula);
CREATE TABLE IF NOT EXISTS notificacion_envios(id TEXT PRIMARY KEY,notificacion TEXT,matricula TEXT NOT NULL,canal TEXT NOT NULL,destino TEXT NOT NULL,payload TEXT NOT NULL,estado TEXT NOT NULL DEFAULT 'PENDIENTE',intentos INTEGER NOT NULL DEFAULT 0,proximo INTEGER NOT NULL DEFAULT 0,lease TEXT,lease_until INTEGER NOT NULL DEFAULT 0,fecha TEXT NOT NULL,aceptado TEXT,error TEXT,UNIQUE(notificacion,canal,destino));
CREATE INDEX IF NOT EXISTS notificacion_cola ON notificacion_envios(estado,proximo,lease_until);
CREATE TABLE IF NOT EXISTS correo_verificaciones(matricula TEXT NOT NULL,tipo TEXT NOT NULL,correo TEXT NOT NULL,hash TEXT NOT NULL,expira INTEGER NOT NULL,intentos INTEGER NOT NULL DEFAULT 0,fecha INTEGER NOT NULL,PRIMARY KEY(matricula,tipo));
CREATE TABLE IF NOT EXISTS documentos_recibidos(folio TEXT PRIMARY KEY,tipo TEXT NOT NULL,registro TEXT NOT NULL,matricula TEXT NOT NULL,actor TEXT NOT NULL,fecha TEXT NOT NULL);
